#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Int8,
    Int16,
    Int32,
    Int64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

impl NumpyDType {
    /// Returns the bit‐width of this dtype.
    pub fn size_bits(&self) -> u32 {
        match self {
            NumpyDType::UInt8   | NumpyDType::Int8    => 8,
            NumpyDType::UInt16  | NumpyDType::Int16   | NumpyDType::Float16 => 16,
            NumpyDType::UInt32  | NumpyDType::Int32   | NumpyDType::Float32 => 32,
            NumpyDType::UInt64  | NumpyDType::Int64   | NumpyDType::Float64 | NumpyDType::Complex64 => 64,
            NumpyDType::Complex128 => 128,
        }
    }

    /// Returns the “kind order” of this dtype:
    ///   Unsigned int = 0, Signed int = 1, Float = 2, Complex = 3.
    pub fn kind_order(&self) -> u8 {
        match self {
            NumpyDType::UInt8  |
            NumpyDType::UInt16 |
            NumpyDType::UInt32 |
            NumpyDType::UInt64   => 0,

            NumpyDType::Int8   |
            NumpyDType::Int16  |
            NumpyDType::Int32  |
            NumpyDType::Int64   => 1,

            NumpyDType::Float16 |
            NumpyDType::Float32 |
            NumpyDType::Float64 => 2,

            NumpyDType::Complex64  |
            NumpyDType::Complex128 => 3,
        }
    }

    /// Returns true if `self` can represent the integer `v`.
    /// Unsigned types only represent ≥ 0; signed types cover all i8;
    /// floats and complexes are assumed to represent any integer.
    pub fn can_represent_i8(&self, v: i8) -> bool {
        match self {
            // unsigned only non‐negative
            NumpyDType::UInt8 |
            NumpyDType::UInt16 |
            NumpyDType::UInt32 |
            NumpyDType::UInt64 => v >= 0,

            // signed ints cover full i8 range
            NumpyDType::Int8 |
            NumpyDType::Int16 |
            NumpyDType::Int32 |
            NumpyDType::Int64 => true,

            // floats & complex always “big enough” for our purposes
            NumpyDType::Float16 |
            NumpyDType::Float32 |
            NumpyDType::Float64 |
            NumpyDType::Complex64 |
            NumpyDType::Complex128 => true,
        }
    }
}

/// Returns the minimal NumPy scalar dtype that can represent the
/// given `i8` value, in the sense that
/// 1) it can represent the value,
/// 2) no smaller‐bit‐width type can,
/// 3) among equal‐width types that can, it has minimal kind_order.
pub fn min_scalar_type(value: i8) -> NumpyDType {
    // List all available dtypes
    const ALL_DTYPES: [NumpyDType; 13] = [
        NumpyDType::UInt8,
        NumpyDType::UInt16,
        NumpyDType::UInt32,
        NumpyDType::UInt64,
        NumpyDType::Int8,
        NumpyDType::Int16,
        NumpyDType::Int32,
        NumpyDType::Int64,
        NumpyDType::Float16,
        NumpyDType::Float32,
        NumpyDType::Float64,
        NumpyDType::Complex64,
        NumpyDType::Complex128,
    ];

    // We will pick the dtype that minimizes (size_bits, kind_order).
    let mut best: Option<NumpyDType> = None;

    for &dt in &ALL_DTYPES {
        if !dt.can_represent_i8(value) {
            continue;
        }
        match best {
            None => {
                best = Some(dt);
            }
            Some(curr) => {
                let curr_key = (curr.size_bits(), curr.kind_order());
                let new_key  = (dt.size_bits(), dt.kind_order());
                if new_key < curr_key {
                    best = Some(dt);
                }
            }
        }
    }

    // We know at least Int8 can always represent any i8,
    // so `best` is guaranteed to be `Some(_)`.
    best.expect("There should always be at least Int8 available")
}

